[2041] = { en = "Speak with Shoni", tier = 1,
  t = "Praat met Shoni",
  d = "Misschien... Misschien kun jij ons helpen in de strijd om Gnomeregan.$B$BIn Stormwind vind je de commandant van onze ondergrondse aanvalsploeg: Shoni the Shilent. Shoni heeft hulp nodig met haar gyrodrillmatic excavationators.$B$BJe vindt haar waarschijnlijk tussen de dwergen in Stormwind.$B$BSucces, $N.",
