[214] = { en = "Red Silk Bandanas", tier = 1,
  t = "Rode zijden bandana's",
  d = "Het is geen geheim: het kenmerk van de Defias Gang is hun rode bandana. Maar we weten nu iets nieuws. De stof van de bandana laat de rang van het lid zien.$b$bDaarom wil ik dat je zoveel mogelijk Defias-leden met een hoge rang uitschakelt. De leden met de hoogste rang zijn zeker in de geheime schuilplaats van VanCleef. Breng me daarna 10 Red Silk Bandanas als bewijs dat ze dood zijn. Dan krijg je een beloning. Succes, $N.",
  o = "Scout Riell bij de Sentinel Hill Tower wil dat je haar 10 Red Silk Bandanas brengt.",
  p = "Heb je ons land teruggenomen van de Defias Gang? Laat me dan 10 Red Silk Bandanas zien als bewijs.",
  c = "Goed gedaan, $N! Namens The People's Militia groet ik je voor je inzet. Binnenkort geven we dit land terug aan het volk, met hulp van dappere mensen zoals jij.",
  g = { {"geheim", "secret"}, {"kenmerk", "trademark, feature"}, {"stof", "fabric, material"}, {"rang", "rank"}, {"uitschakelt", "eliminate (uitschakelen)"}, {"schuilplaats", "hideout"}, {"bewijs", "proof"}, {"teruggenomen", "taken back (terugnemen)"}, {"namens", "on behalf of"}, {"inzet", "effort"}, {"dappere", "brave (dapper)"} },
},

[168] = { en = "Collecting Memories", tier = 1,
  t = "Herinneringen verzamelen",
  d = "Veel van mijn vrienden zijn gestorven op die vreselijke dag, toen de mijngang instortte. Kom je tijdens je avonturen in dat deel van de mijn in Moonbrook? Let dan alsjeblieft op tekens die laten zien wie ze waren. Als je hun Miners' Union Cards vindt, breng ze dan terug naar mij. Dan zorg ik ervoor dat hun families duidelijkheid krijgen over dit vreselijke ongeluk.",
  o = "Haal 4 Miners' Union Cards op en breng ze terug naar Wilder Thistlenettle in Stormwind.",
  p = "Heb je Miners' Union Cards van mijn oude collega's gevonden?",
  c = "Bedankt dat je deze hebt verzameld, $N. Door jou kunnen de doden rust vinden na deze ramp. Ik zorg ervoor dat de families het bericht krijgen.",
  g = { {"herinneringen", "memories (herinnering)"}, {"vreselijke", "horrible (vreselijk)"}, {"mijngang", "mine tunnel"}, {"instortte", "caved in (instorten)"}, {"tekens", "signs (teken)"}, {"duidelijkheid", "clarity, resolution"}, {"ongeluk", "accident"}, {"collega's", "co-workers (collega)"}, {"rust", "peace, rest"}, {"ramp", "tragedy, disaster"} },
},

[167] = { en = "Oh Brother. . .", tier = 1,
  t = "O, broer...",
  d = "We waren diep in een grote mijn in Westfall. Die zit verstopt onder een schuur in Moonbrook. Ik heb geen idee waar die stinkende dieven vandaan kwamen. Hoe dan ook, de mijngang stortte op ons in. Ik kwam eruit, maar de anderen... nou... van de anderen hebben we niets meer gehoord.$b$bJij ziet eruit alsof je daar meer geluk kunt hebben. Wil je zoeken naar mijn broer? Dan ben ik je dankbaar. Hij had altijd zijn Explorers' League Badge bij zich. Vind je hem niet, dan geeft die badge me tenminste wat rust.",
  o = "Breng Foreman Thistlenettle's Explorers' League Badge naar Wilder Thistlenettle in Stormwind.",
  p = "Heb je iets van mijn broer gevonden? Is er na al die tijd nog hoop?",
  c = "Ik had dus gelijk. Mijn arme broer... Nou, bedankt dat je dit raadsel hebt opgelost, ook al is het einde somber.",
  g = { {"verstopt", "hidden (verstoppen)"}, {"schuur", "barn"}, {"stinkende", "stinking (stinkend)"}, {"dieven", "thieves (dief)"}, {"hoe dan ook", "anyway"}, {"stortte", "collapsed (instorten)"}, {"dankbaar", "thankful"}, {"tenminste", "at least"}, {"raadsel", "mystery, riddle"}, {"opgelost", "solved (oplossen)"}, {"somber", "grim, gloomy"} },
},

[1132] = { en = "Fiora Longears", tier = 1,
  t = "Fiora Longears",
  d = "Oh, was ik maar weer op zee! De kus van de wind voelen, en de golven die me wiegen zoals mijn lieve moeder, lang geleden!$B$BOh, had ik maar jouw geluk, beste $c, want ik zie de zee in jouw toekomst!$B$BHet is mijn werk om enthousiaste mensen te vertellen over het land Kalimdor, het land van de kansen! Wil je je geluk proberen aan de andere kant van de zee? Neem dan hier een schip naar de mooie haven van Theramore. Praat daar met mijn partner, de elf Fiora Longears.$B$BZij laat je je avontuur in Kalimdor beginnen!",
  o = "Praat met Fiora Longears in Theramore.",
  c = "Goedendag! Heeft meneer Flint in Menethil Harbor je gestuurd? Nou, meneer Flint kan mensen goed beoordelen. Als hij jou heeft gestuurd, dan hoor je hier in Kalimdor, zeker weten!",
  g = { {"was ik maar", "if only I were"}, {"golven", "waves (golf)"}, {"wiegen", "to rock (a cradle)"}, {"geluk", "luck, fortune"}, {"toekomst", "future"}, {"enthousiaste", "eager (enthousiast)"}, {"kansen", "opportunities (kans)"}, {"haven", "port, harbor"}, {"beoordelen", "to judge"}, {"zeker weten", "no doubt, for sure"} },
},

[1649] = { en = "The Tome of Valor", tier = 1,
  t = "Het boek van moed",
  d = "Moed, en alle deugden die daarbij horen, zijn als zeldzame mineralen. Je moet ze koesteren als je ze vindt, omdat ze veel waard zijn. Maar je moet ook de tijd nemen om ze te oogsten... en te zuiveren. Als je ze goed mengt, dan krijg je een sterke legering. Soms kunnen zelfs de hardste klappen die niet breken.$B$BDeze kracht, jouw geloof, jouw moed, moet getest worden. Je moet leren om nooit je geloof te verliezen. En je moet begrijpen dat je met de kracht van het Licht dingen kunt overwinnen die de meeste anderen niet kunnen overwinnen.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Ah, je wilt mij vragen om een test van moed. Prachtig.$B$BIn de stad en het land eromheen zijn veel taken die een grote uitdaging zijn. Ze kunnen een $gman:vrouw; met jouw vaardigheden goed gebruiken.$B$BNeem deze test niet te licht op, $N. Net als veel dingen op ons pad kan deze test ons het leven kosten. De Kerk wil altijd graag haar rijen versterken. Maar ze begrijpt ook dat er offers nodig zijn. Zo weet ze zeker dat de paladijnen die haar dienen het waard zijn.$B$BBen je er klaar voor?",
  g = { {"moed", "courage, valor"}, {"deugden", "virtues (deugd)"}, {"zeldzame", "rare (zeldzaam)"}, {"koesteren", "to cherish"}, {"oogsten", "to harvest"}, {"zuiveren", "to refine, to purify"}, {"legering", "alloy"}, {"klappen", "blows (klap)"}, {"geloof", "faith"}, {"overwinnen", "to overcome"}, {"uitdaging", "challenge"}, {"vaardigheden", "skills (vaardigheid)"}, {"rijen versterken", "to strengthen the ranks"}, {"offers", "sacrifices (offer)"} },
},

[2040] = { en = "Underground Assault", tier = 1,
  t = "Ondergrondse aanval",
  d = "Gnomeregan is in handen gevallen van die gemene troggs! De situatie is ernstig, maar misschien kun jij helpen, $N.$B$BDiep in de Deadmines staat een goblin shredder die nog werkt. Zoek die shredder en breng de energiebron in één stuk terug. Met die energiebron geven we onze gyrodrillmatic excavationators de kracht die ze nodig hebben. Dan kunnen ze door de rotsachtige ondergrondse grenzen van Gnomeregan breken. Zo openen we de weg voor een aanval van de gnomen!",
  o = "Haal de Gnoam Sprecklesprocket uit de Deadmines en breng hem terug naar Shoni the Shilent in Stormwind.",
  p = "Heb je de Gnoam Sprecklesprocket gevonden, $N?",
  c = "Goed gedaan, $N. Dankzij jou is Gnomeregan weer een stap dichter bij de dag van zijn bevrijding!",
  g = { {"in handen gevallen", "fallen into the hands (vallen)"}, {"gemene", "nasty, dastardly (gemeen)"}, {"ernstig", "grave, serious"}, {"energiebron", "power supply"}, {"in één stuk", "intact, in one piece"}, {"rotsachtige", "rocky (rotsachtig)"}, {"grenzen", "borders (grens)"}, {"dankzij", "thanks to"}, {"dichter bij", "closer to"}, {"bevrijding", "liberation"} },
},

[276] = { en = "Tramping Paws", tier = 2,
  t = "Stampende poten",
  d = "De Mosshide Gnolls wonen al vele jaren vreedzaam in de Wetlands. Maar nu worden het er steeds meer. Hun voeten stampen de struiken en bloemen van het moeras plat. En met hun smerige bijlen hakken ze te veel hout voor hun vuren.$B$BZe zijn niet meer in evenwicht met het land. Als de Wetlands willen overleven, moeten er minder gnolls komen.$B$BDood 15 Mosshide Gnolls en 10 Mosshide Mongrels. Jaag op ze in het zuiden, bij de dwergenpoort van Algaz. Kom daarna terug naar mij.",
  o = "Dood 15 Mosshide Gnolls en 10 Mosshide Mongrels. Ga daarna terug naar Rethiel the Greenwarden in de Wetlands.",
  p = "Je taak is nog niet klaar, jonge $C.",
  c = "Je hebt het aantal gnolls kleiner gemaakt. Zo heb je voor de gezondheid van de Wetlands gezorgd. Mijn vertrouwen in jouw volk is in het verleden zwaar op de proef gesteld, $R. Maar misschien komt het toch nog terug.",
  g = { {"stampende", "tramping (stampen)"}, {"poten", "paws (poot)"}, {"vreedzaam", "peacefully"}, {"struiken", "bushes (struik)"}, {"moeras", "marsh, fen"}, {"smerige", "foul, filthy (smerig)"}, {"bijlen", "axes (bijl)"}, {"hakken", "to chop"}, {"evenwicht", "balance"}, {"overleven", "to survive"}, {"dwergenpoort", "dwarven gate"}, {"aantal", "number"}, {"vertrouwen", "faith, trust"}, {"op de proef gesteld", "put to the test, taxed"} },
},

[455] = { en = "The Algaz Gauntlet", tier = 2,
  t = "De tocht door Algaz",
  d = "Orks van de Dragonmaw-clan hebben een schuilplaats in de Wetlands. En nu zijn ze ook in Dun Algaz gekomen! We mogen ze hier geen voet aan de grond laten krijgen. Anders wordt Loch Modan afgesneden van Menethil Harbor, onze haven en vesting in de Wetlands.$B$BBreek door Dun Algaz heen naar de Wetlands erachter. En dood er meteen wat orks bij! Meld je bij Valstag Ironjaw in Menethil Harbor.$B$BJe komt in Menethil door Dun Algaz te gaan, dan naar het noorden over de weg, en dan naar het westen bij de splitsing.$B$BWe rekenen op je, $N. Laat ons niet in de steek.",
  o = "Trek door Dun Algaz.$B$BDood 8 Dragonmaw Scouts en 6 Dragonmaw Grunts.$B$BMeld je bij Valstag Ironjaw in Menethil Harbor.",
  p = "Kom je uit Loch Modan? Hoe is het met de orks bij Algaz Gate?",
  c = "Je verslag zit vol slecht nieuws!$b$bIk zie dat de Dragonmaws met veel kracht Algaz binnentrekken. Normaal verstoppen de Dragonmaws zich gewoon in de heuvels. Waarom ze nu Algaz in stromen, is nog een raadsel...$b$bBedankt, $N. En we willen waarschijnlijk je hulp om deze orks aan te pakken.",
  e = "Trek door Dun Algaz",
  g = { {"tocht", "journey, trek"}, {"schuilplaats", "haven, hideout"}, {"voet aan de grond", "foothold"}, {"afgesneden", "cut off (afsnijden)"}, {"vesting", "stronghold"}, {"meld je", "report (zich melden)"}, {"splitsing", "fork (in the road)"}, {"rekenen op", "to count on"}, {"in de steek laten", "to let down, to fail"}, {"verslag", "report"}, {"binnentrekken", "to move into"}, {"stromen", "to stream, to surge"}, {"aan te pakken", "to deal with (aanpakken)"} },
},

[463] = { en = "The Greenwarden", tier = 2,
  t = "De Greenwarden",
  d = "Heb je over de Greenwarden gehoord? Je gaat hem toch niet zoeken? Nou, dan ben je gek, zeg ik. Maar wie ben ik om een dwaas tegen te houden die naar $gzijn:haar; dood gaat?$B$BAls je dat beest zoekt, dan hoor ik dat hij in het moeras is, ten oosten van de weg waar die splitst naar Dun Modr. Hij sluipt daar rond tussen de krokodillen... en erger!$B$BEn laat je geld hier. Dat heb je niet nodig waar je heen gaat... En je wilt toch niet dat ouwe Greenie een tand breekt op je goud, als hij je doormidden bijt?",
  o = "Zoek de Greenwarden.",
  c = "De wortels en varens spreken goed over je, kleintje. Ik heb veel namen, maar ik luister maar naar een paar. Je mag me Rethiel noemen.$B$BEn je moet goed luisteren... want dit land huilt om zijn etterende wonden. En ik wil jou de taak geven om ze te genezen.",
  g = { {"gek", "crazy"}, {"dwaas", "fool"}, {"tegen te houden", "to stop, to keep from (tegenhouden)"}, {"beest", "beast"}, {"splitst", "forks (splitsen)"}, {"sluipt", "lurks, sneaks (sluipen)"}, {"krokodillen", "crocodiles (krokodil)"}, {"ouwe", "old (informal, oud)"}, {"doormidden", "in half"}, {"wortels", "roots (wortel)"}, {"varens", "ferns (varen)"}, {"etterende", "festering (etteren)"}, {"wonden", "wounds (wond)"}, {"genezen", "to heal"} },
},

[468] = { en = "Report to Mountaineer Rockgar", tier = 2,
  t = "Meld je bij Mountaineer Rockgar",
  d = "Mountaineer Rockgar zoekt vrijwilligers voor een missie door Dun Algaz naar de Wetlands.$B$BWil je je laarzen nat maken in dat drassige gebied in het noorden? Praat dan met Rockgar bij Dun Algaz. Dun Algaz ligt in het noorden, verder over de weg, voorbij de wachttoren.",
  o = "Praat met Mountaineer Rockgar.",
  c = "Hallo, $C! Je komt voor de verkenningsmissie, toch? Heel goed!$b$bIk hoop dat je uitrusting in goede staat is. Want deze \"verkenningsmissie\" is iets veel rommeligers geworden...",
  g = { {"meld je", "report (zich melden)"}, {"vrijwilligers", "volunteers (vrijwilliger)"}, {"laarzen", "boots (laars)"}, {"drassige", "soggy (drassig)"}, {"voorbij", "beyond, past"}, {"wachttoren", "guard tower"}, {"verkenningsmissie", "scouting mission"}, {"uitrusting", "gear, equipment"}, {"in goede staat", "in good condition"}, {"rommeligers", "messier (rommelig)"} },
},

[469] = { en = "Daily Delivery", tier = 2,
  t = "Dagelijkse levering",
  d = "Gegroet, reiziger!$b$bJij gaat zeker niet toevallig richting Menethil? Als dat niet zo is, raad ik je aan om daar te stoppen. Het is een goede plek om spullen te kopen. Je kunt er zelfs een biertje drinken en ontspannen.$b$bNou, als je toevallig die kant op gaat, wil je dan deze bundel crocolisk-huiden naar James Halloran brengen, de leerlooier?$b$bIk zou het zelf doen. Maar mijn vrouw is de laatste tijd nogal slecht gehumeurd, en ik wil haar zo lang mogelijk ontlopen.",
  o = "Breng de Bundle of Crocolisk Skins naar James Halloran, de leerlooier, in Menethil Harbor.",
  p = "Hallo, $C. Heb je misschien interesse in een paar laarzen? Of in wat pas gelooide huiden?",
  c = "Hm, dit komt van Einar, toch? Hij heeft me zijn huiden al bijna een week niet zelf gebracht. Vast weer wat onenigheid met zijn vrouw!$b$bMisschien laat ik mijn vrouw een keer met Sida gaan praten...",
  g = { {"dagelijkse", "daily (dagelijks)"}, {"levering", "delivery"}, {"gegroet", "greetings"}, {"toevallig", "by chance"}, {"richting", "in the direction of"}, {"raad ik je aan", "I'd suggest (aanraden)"}, {"ontspannen", "to relax"}, {"bundel", "bundle"}, {"huiden", "skins, hides (huid)"}, {"leerlooier", "tanner"}, {"slecht gehumeurd", "in a bad mood"}, {"ontlopen", "to avoid"}, {"gelooide", "cured, tanned (looien)"}, {"onenigheid", "disagreement, differences"} },
},

[1653] = { en = "The Test of Righteousness", tier = 2,
  t = "De test van rechtvaardigheid",
  d = "Eigenlijk weet ik zeker dat Jordan je zelf graag wil bedanken. En ik heb een boodschapper nodig om te laten weten dat zijn vrouw veilig is. Dus ik denk dat jij perfect bent.$B$BJordan zou eerst een paladijn van het Licht worden. Maar zijn toewijding aan het vak van zijn vader bracht hem op een ander pad. Hij kent onze manier van leven heel goed, en hij hoort bij onze trouwste gelovigen.$B$BHij is vast nog in Ironforge. Overdag werkt hij graag buiten de poorten. Iets met de koele berglucht.",
  o = "Praat met Jordan Stilwell in Ironforge",
  c = "Goedendag, $n. Het Licht is met je, hoop ik?$b$bWat zeg je? Duthorian heeft je gestuurd!? Mijn vrouw, hoe gaat het met haar? Ik wist dat er problemen zouden komen als ik wegging. Zeg me alsjeblieft dat ze... oh, gelukkig maar. Ik ben zo blij dat ze veilig is. De Defias waren al lang voor deze aanvallen een gevaar. Maar nu kunnen de adviseurs van de koning het niet meer ontkennen.$b$bWat zei Duthorian nog meer?$b$bJij bent degene die mijn vrouw moest beschermen? Dan bedank ik je nog een keer, $n. Ik kan geen betere test van moed bedenken.",
  g = { {"rechtvaardigheid", "righteousness"}, {"boodschapper", "messenger"}, {"toewijding", "dedication"}, {"vak", "craft, trade"}, {"trouwste", "most faithful (trouw)"}, {"gelovigen", "believers (gelovige)"}, {"overdag", "during the day"}, {"poorten", "gates (poort)"}, {"koele", "cool (koel)"}, {"adviseurs", "advisors (adviseur)"}, {"ontkennen", "to deny"}, {"degene", "the one (person)"} },
},

[166] = { en = "The Defias Brotherhood", tier = 2,
  t = "De Defias Brotherhood",
  d = "Er is nog maar één taak voor je over. Edwin VanCleef moet vermoord worden. Het maakt me verdrietig om iemand ter dood te veroordelen. Maar voor het welzijn van het volk van Westfall moet VanCleef voorgoed in zijn graf liggen. Breng me het hoofd van de schurk als het klaar is.",
  o = "Dood Edwin VanCleef en breng zijn hoofd naar Gryan Stoutmantle.",
  p = "Hoe gaat de jacht op Edwin VanCleef?",
  c = "$N, je moed is bijzonder. The People's Militia bedankt je voor je dienst aan het volk van Westfall. Nu VanCleef dood is, begint het einde van de Defias Brotherhood. Hopelijk is er snel weer vrede op de vlaktes van dit mooie land.$B$BIk groet je, $gheer:vrouwe;!",
  g = { {"vermoord", "assassinated, murdered (vermoorden)"}, {"verdrietig", "sad"}, {"ter dood te veroordelen", "to condemn to death"}, {"welzijn", "well-being, good"}, {"voorgoed", "for good, once and for all"}, {"graf", "grave"}, {"jacht", "hunt"}, {"dienst", "service"}, {"hopelijk", "hopefully"}, {"vlaktes", "plains (vlakte)"}, {"vrouwe", "lady (noble title)"} },
},

[279] = { en = "Claws from the Deep", tier = 2,
  t = "Klauwen uit de diepte",
  d = "Murlocs kruipen uit het diepe water en bouwen hun dorpen langs de kust. Ze vallen onze vissers en handelaars lastig, en dat moet stoppen.$B$BEen van die murlocs, Gobbler, sluipt rond met andere bluegill murlocs. Hij valt handelaars op de weg aan, en daarna vlucht hij altijd terug naar de veilige murlochutten in de buurt. Onze handelaars zijn in gevaar, en we betalen om ze te beschermen.$B$BGobbler loopt rond bij de inham van de rivier, ten noorden van hier. Zoek hem, dood zijn soortgenoten en breng me zijn hoofd.",
  o = "Dood 12 Bluegill Murlocs.$B$BDood Gobbler en neem zijn hoofd mee.$B$BBreng Gobbler's Head naar Karl Boran in Menethil Harbor.",
  p = "Onze handelaars zijn pas veilig als we van Gobbler en die murlocs af zijn.",
  c = "Ah, goed gedaan, $N.$b$bNeem dit aan als betaling, nu je je contract met de Merchant Marines hebt uitgevoerd.",
  g = { {"klauwen", "claws (klauw)"}, {"diepte", "the deep, depth"}, {"kruipen", "to crawl"}, {"kust", "coast"}, {"vallen lastig", "harass (lastigvallen)"}, {"handelaars", "merchants (handelaar)"}, {"vlucht", "flees, retreats (vluchten)"}, {"murlochutten", "murloc hovels (hut)"}, {"inham", "inlet"}, {"soortgenoten", "kin, own kind (soortgenoot)"}, {"af zijn", "be rid of (van iets af zijn)"}, {"uitgevoerd", "fulfilled, carried out (uitvoeren)"} },
},

[373] = { en = "The Unsent Letter", tier = 2,
  t = "De onverstuurde brief",
  d = "Je doorzoekt Edwin VanCleef. Tussen andere dingen vind je een brief die nooit verstuurd is. Hij is gericht aan Baros Alexston, de stadsarchitect van Stormwind, City Hall, Cathedral Square.$B$BHet lijkt erop dat hij pas geschreven en verzegeld is.",
  o = "Breng de Letter to the City Architect naar Baros Alexston in Stormwind.",
  p = "Ja? Kan ik je ergens mee helpen?",
  c = "Edwin VanCleef, zeg je? Dan verwacht ik net zo goed een brief van mijn dode oma... Dus je hebt hem gedood? Neem me niet kwalijk, maar dat verbaast me een beetje. Toen hij jonger was, was hij een vechter zonder gelijke. Eens kijken waarom hij me na zoveel jaren wil schrijven.$b$b<Baros leest de brief zorgvuldig.>$b$bEdwin... Ik zie dat de jaren je niets veranderd hebben. Je bent nog altijd een idealist, en een romanticus. Het maakt hem niet uit wie hij pijn doet, $N. Wraak heeft hem helemaal opgevreten. Maar ja, ik weet niet zeker of ik hem dat kwalijk kan nemen.",
  g = { {"onverstuurde", "unsent (onverstuurd)"}, {"doorzoekt", "search (doorzoeken)"}, {"gericht aan", "addressed to"}, {"stadsarchitect", "city architect"}, {"verzegeld", "sealed (verzegelen)"}, {"neem me niet kwalijk", "pardon me"}, {"verbaast", "surprises (verbazen)"}, {"zonder gelijke", "peerless, without equal"}, {"zorgvuldig", "carefully"}, {"wraak", "revenge"}, {"opgevreten", "consumed, eaten up (opvreten)"}, {"kwalijk nemen", "to blame"} },
},

[484] = { en = "Young Crocolisk Skins", tier = 2,
  t = "Huiden van jonge crocolisken",
  d = "Ik ben James Halloran, de leerlooier. Mijn gelooide crocolisk-huiden zijn overal gewild. Ze gaan per boot naar havens over de hele wereld.$b$bHeb je Einar ontmoet? Hij is een van de jagers die crocolisk-huiden voor me brengen.$b$bIk heb te weinig van de zachtere huiden van jonge crocolisken.$b$bOmdat ik bijna niets meer heb, betaal ik je goed voor een stapel van die huiden. Je vindt de jonge crocolisken in de moerassen vlak buiten de stad.",
  o = "Haal 4 Young Crocolisk Skins voor James Halloran in Menethil Harbor.",
  p = "$N, toch? Heb je mijn huiden?",
  c = "Mooi werk, $N. De kwaliteit van deze huiden is uitstekend. Ik moet ze zo snel mogelijk gaan looien. Oh, maar voordat ik daaraan begin: ik heb nog ander werk dat gedaan moet worden. Ik denk dat jij dat misschien kunt doen.",
  g = { {"leerlooier", "tanner"}, {"gelooide", "cured, tanned (looien)"}, {"gewild", "sought after"}, {"havens", "ports (haven)"}, {"jagers", "hunters (jager)"}, {"zachtere", "softer (zacht)"}, {"stapel", "stack, pile"}, {"moerassen", "marshes (moeras)"}, {"vlak buiten", "right outside"}, {"uitstekend", "superb, excellent"}, {"looien", "to tan, to cure (leather)"} },
},

[1654] = { en = "The Test of Righteousness", tier = 2,
  t = "De test van rechtvaardigheid",
  d = "Ik wil je graag belonen, als je zoiets wilt aannemen? Begrijp me niet verkeerd. Hoe vrijgevig ik ben, hangt af van hoeveel je kunt helpen. Maar ik denk dat we allebei veel aan zo'n samenwerking hebben.$B$BIk maak voor jou een wapen dat past bij wat je hebt gedaan, een symbool van het paladijnschap en het Licht. Maar jij moet de spullen verzamelen die ik nodig heb om het te maken. Ik heb al aantekeningen gemaakt over de spullen. Er is alleen iemand nodig die dapper en handig genoeg is om ze te halen. Wat zeg je ervan, $c?",
  o = "Gebruik Jordan's Weapon Notes en zoek Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer en een Kor Gem. Breng ze terug naar Jordan Stilwell in Ironforge.",
  p = "De spullen die je zoekt, zijn moeilijk te krijgen. Maar ik beloof je: het wapen dat ik voor je maak, is de moeite waard.$B$BHet wordt mijn beste werk tot nu toe. En het is maar een kleine betaling voor wat je voor mij hebt gedaan.",
  c = "Dit is geweldig! Je hebt alle spullen gevonden.$B$BHiermee kan ik zonder problemen een prachtig wapen voor je smeden. Ik heb de plannen hiervoor eigenlijk al een tijdje. Ik had alleen nooit de kans om de spullen te verzamelen. Bedankt, $N.$B$BHet voelt goed om de hamer van mijn vader weer te hebben... en een Kor-edelsteen. Ik had nooit gedacht dat ik er zelf een zou zien.",
  g = { {"belonen", "to reward"}, {"aannemen", "to accept"}, {"vrijgevig", "generous"}, {"hangt af van", "depends on (afhangen)"}, {"samenwerking", "alliance, cooperation"}, {"paladijnschap", "paladinhood"}, {"aantekeningen", "notes (aantekening)"}, {"handig", "skilled, handy"}, {"de moeite waard", "worth the effort"}, {"betaling", "payment"}, {"smeden", "to forge"}, {"edelsteen", "gem"} },
},

[277] = { en = "Fire Taboo", tier = 2,
  t = "Vuurtaboe",
  d = "De Mosshides hakken de bomen van de Wetlands om. Ze gebruiken het vlees van de bomen om zich te warmen aan het vuur. Ik verdraag deze pijn niet langer!$B$BNeem de Mosshides hun ruwe vuurstenen af, het gereedschap waarmee ze vuur maken. Alle Mosshides dragen die vuurstenen, behalve de kleinere Mosshide gnolls en Mosshide mongrels.",
  o = "Breng Rethiel the Greenwarden 9 Crude Flints.",
  p = "Heb je het gereedschap waarmee de gnolls vuur maken?",
  c = "... dank je. Ik sla deze vuurstenen kapot en gooi ze in de zee. Dan kunnen ze nooit meer gebruikt worden om levend hout te verbranden.",
  g = { {"taboe", "taboo"}, {"hakken om", "chop down (omhakken)"}, {"vlees", "flesh, meat"}, {"verdraag", "suffer, endure (verdragen)"}, {"ruwe", "crude, rough (ruw)"}, {"vuurstenen", "flints (vuursteen)"}, {"gereedschap", "tools"}, {"behalve", "except"}, {"sla kapot", "smash (kapotslaan)"}, {"verbranden", "to burn"} },
},

[1650] = { en = "The Tome of Valor", tier = 2,
  t = "Het boek van moed",
  d = "Goed! Dat je niet twijfelt, is een duidelijk teken. Je bent klaar en je wilt jezelf graag testen. Goed dan.$B$BHelemaal aan het einde van Longshore in Westfall staat een klein huis met uitzicht op de oceaan. Daar woont een stel, de Stilwells. Jordan is een geweldige smid. Hij is een tijdje naar Ironforge om met de dwergen te praten. Maar daardoor is Daphne, zijn vrouw, alleen en onbeschermd.$B$BVolgens berichten hebben de Defias het gebied bijna helemaal overgenomen. Daphne heeft misschien wat bescherming nodig tegen de schurken. Ga erheen.",
  o = "Zoek Daphne Stilwell in Westfall.",
  c = "Hallo, $N. Ik zie al dat harnas en dat wapen van je. Dus ik neem aan dat je hier bent om mijn land af te pakken. Of de Kerk heeft eindelijk iemand gestuurd om mij te beschermen, nu mijn Jordan weg is.$B$BNou, laat ik me even voorstellen: ik ben Daphne Stilwell. Aangenaam.$B$BJe bent niet te laat... Ik heb pas een stuk of zes van dat tuig gedood sinds de laatste zonsopgang. Ze zijn een beetje traag om daarboven de bocht om te komen. Maar ze hebben jou waarschijnlijk zien aankomen. Dat betekent dat ze hier waarschijnlijk elk moment kunnen zijn.",
  g = { {"twijfelt", "hesitate, doubt (twijfelen)"}, {"teken", "sign"}, {"uitzicht", "view"}, {"stel", "couple"}, {"smid", "smith"}, {"onbeschermd", "unprotected"}, {"overgenomen", "taken over (overnemen)"}, {"schurken", "villains (schurk)"}, {"harnas", "armor"}, {"neem aan", "assume (aannemen)"}, {"voorstellen", "to introduce"}, {"Aangenaam", "Pleased to meet you"}, {"tuig", "scum, riffraff"}, {"zonsopgang", "sunrise"}, {"bocht", "bend, curve"} },
},

[294] = { en = "Ormer's Revenge", tier = 2,
  t = "Ormers wraak",
  d = "De situatie is ernstig, dat is zeker. Toen we deze botten opgroeven, trok dat de raptors aan. Die smerige beesten hebben mijn broeders gedood. Mij, Merrin en de arme Prospector hebben ze hierboven ingesloten.$b$bHelp om de Wetlands van deze raptors te bevrijden, $N. Mottled Raptors en Mottled Screechers zitten net ten westen van de rotswand daar. Dood er van elk 10, als het lukt.$b$bDat is een goed begin van de wraak die ik voor ze heb gepland.",
  o = "Ormer Ironbraid bij de Whelgar Excavation Site wil dat je 10 Mottled Screechers en 10 Mottled Raptors doodt.",
  p = "Dood 10 Mottled Raptors en 10 Mottled Screechers, $N. Mijn collega's verdienden het lot niet dat ze kregen. Het is tijd om de rekening te vereffenen.",
  c = "Doden is vies werk, maar je hebt je werk goed gedaan, $N. Als ik niet bij de Prospector en Merrin moest blijven, zou ik daar beneden naast je bloed vergieten.",
  g = { {"ernstig", "severe, serious"}, {"botten", "bones (bot)"}, {"opgroeven", "dug up (opgraven)"}, {"trok aan", "attracted (aantrekken)"}, {"broeders", "brethren (broeder)"}, {"ingesloten", "trapped (insluiten)"}, {"bevrijden", "to free, to clear"}, {"rotswand", "bluff, rock face"}, {"verdienden", "deserved (verdienen)"}, {"lot", "fate"}, {"de rekening vereffenen", "to even the score"}, {"vies", "dirty"}, {"vergieten", "to shed (blood)"} },
},

[305] = { en = "In Search of The Excavation Team", tier = 2,
  t = "Op zoek naar het opgravingsteam",
  d = "O, jij bent vast de verkenner die Longbraid zou sturen! Je kunt je niet voorstellen hoe ongerust ik ben geweest.$b$bMijn vrouw, Merrin, stuurt me al een maand elke week brieven. Ze hoort bij het opgravingsteam van Whelgar. Maar haar laatste brief is al bijna twee weken geleden. Er is vast iets mis!$b$bLongbraid zei dat hij een verkenner zou sturen om te kijken hoe het gaat, als we niet snel iets van het team hoorden. Ik neem aan dat jij die verkenner bent, $N. Zoek Merrin bij de opgravingsplek in het oosten!",
  o = "Tarrel Rockweaver wil dat je naar de Excavation Site reist en contact opneemt met Merrin Rockweaver.",
  c = "O, de hemel zij dank, je bent er!",
  g = { {"opgravingsteam", "excavation team"}, {"verkenner", "scout"}, {"voorstellen", "to imagine (zich voorstellen)"}, {"ongerust", "worried"}, {"neem aan", "assume (aannemen)"}, {"opgravingsplek", "excavation site"}, {"contact opneemt", "make contact (contact opnemen)"}, {"de hemel zij dank", "thank the heavens"} },
},

[306] = { en = "In Search of The Excavation Team", tier = 2,
  t = "Op zoek naar het opgravingsteam",
  d = "Het was vreselijk! We waren zeldzame voorwerpen aan het opgraven, en toen vonden we deze grote botten.$b$bVoordat we wisten wat er gebeurde, overvielen die Mottled Raptors de opgraving. Er zijn veel levens verloren.$b$bOrmer hier... zo dapper... heeft de Prospector en mij gered. Hij verdedigde ons terwijl we naar een schuilplaats renden. Nu zitten we vast. En ons harde werk ligt in puin.$b$bHier, neem dit briefje mee terug naar mijn lieve Tarrel. Daarin leg ik hem de situatie uit.",
  o = "Ga terug naar Tarrel Rockweaver met het briefje van Merrin.",
  p = "Heb je Merrin gevonden? Heeft ze een bericht gestuurd?",
  c = "Wat een vreselijk nieuws! Er zijn er tenminste 3 overleefd. Maar wanneer houdt het doden op? Ik verlang naar de dag dat de onderdanen van koning Magni zonder angst kunnen leven.",
  g = { {"voorwerpen", "artifacts, objects (voorwerp)"}, {"opgraven", "to dig up, to excavate"}, {"overvielen", "overwhelmed, raided (overvallen)"}, {"opgraving", "dig site, excavation"}, {"gered", "saved (redden)"}, {"verdedigde", "defended (verdedigen)"}, {"schuilplaats", "shelter"}, {"zitten vast", "are trapped (vastzitten)"}, {"in puin", "in ruins"}, {"overleefd", "survived (overleven)"}, {"verlang naar", "long for (verlangen)"}, {"onderdanen", "subjects (onderdaan)"}, {"angst", "fear"} },
},

[470] = { en = "Digging Through the Ooze", tier = 2,
  t = "Zoeken in het slijm",
  d = "Tijdens mijn wekelijkse bezoek aan Ironbeard's Tomb werd ik aangevallen door vreselijke, druipende slijmmonsters! Natuurlijk raakte ik in paniek.$b$bIk gooide mijn tas naar een van ze, maar dat hielp niets! Het slijmmonster zoog hem gewoon op... Gelukkig had ik daardoor genoeg tijd om weg te komen.$b$bHet slechte nieuws is dat ik de inhoud van mijn tas echt nodig heb!$b$bIk weet niet naar welk slijmmonster ik mijn tas gooide; ze zagen er allemaal hetzelfde uit! Ironbeard's Tomb ligt ten noordoosten van hier, bij Dun Modr. Heel erg bedankt!",
  o = "Een van de slijmmonsters bij Ironbeard's Tomb heeft de tas van Sida. Haal hem terug en breng hem naar haar in Menethil Harbor.",
  p = "Heb je mijn tas gevonden?",
  c = "Oh, dank je, $N! Ik was bang dat ik hem voorgoed kwijt was!$B$B<Ze schudt de tas vol slijm snel leeg op de grond, en raapt dan alles weer op.>$B$BHm, dit heb ik niet zo veel meer nodig. Maar als je het afwast, heb jij er vast iets aan.",
  g = { {"slijm", "slime, ooze"}, {"wekelijkse", "weekly (wekelijks)"}, {"druipende", "dripping (druipen)"}, {"slijmmonsters", "oozes (slijmmonster)"}, {"raakte in paniek", "panicked (in paniek raken)"}, {"zoog op", "sucked up (opzuigen)"}, {"inhoud", "contents"}, {"voorgoed", "for good"}, {"kwijt", "lost"}, {"schudt leeg", "empties (leegschudden)"}, {"raapt op", "scoops up (oprapen)"}, {"afwast", "wash off (afwassen)"} },
},

[281] = { en = "Reclaiming Goods", tier = 2,
  t = "Spullen terughalen",
  d = "Niet lang geleden werd een handelsschip, de Blind Princess, overvallen door murlocs. Het schip ontsnapte zonder schade. Maar de wezens hebben veel van de lading overboord getrokken. Daarbij was ook een heel waardevol beeldje van Terenas Menethil. We willen dat beeldje terug.$B$BDoorzoek de murlochutten aan de kust op kisten, vaten en andere sporen van verloren lading. Zoek de Menethil Statuette en breng hem terug naar mij.",
  o = "Doorzoek de kisten en vaten in de murlockampen aan de kust.",
  c = "Deze kist zit vol krassen van klauwen en sporen van waterschade. Je wrikt hem open en ziet nat, verrot stro. Het lijkt alsof er iets waardevols in de kist zat. Je zoekt door het stro...$B$B...en vindt een armvol rode flessen.",
  g = { {"handelsschip", "merchant vessel"}, {"overvallen", "raided (overvallen)"}, {"ontsnapte", "escaped (ontsnappen)"}, {"schade", "damage"}, {"lading", "cargo"}, {"overboord", "overboard"}, {"beeldje", "statuette"}, {"kisten", "crates (kist)"}, {"vaten", "barrels (vat)"}, {"sporen", "traces, evidence, marks (spoor)"}, {"krassen", "scratches (kras)"}, {"wrikt open", "pry open (openwrikken)"}, {"verrot", "rotted"}, {"stro", "straw"}, {"armvol", "armload"} },
},

[284] = { en = "The Search Continues", tier = 2,
  t = "De zoektocht gaat door",
  d = "Je doorzoekt deze groep murlochutten grondig, maar je vindt geen spoor van de Menethil Statuette.$B$BMisschien heeft een van de twee hutten in de buurt, in het noorden en noordoosten, meer aanwijzingen.",
  o = "Zoek naar de Menethil Statuette.",
  c = "Dit vat is bijna niet aangeraakt. Je wrikt het open...$B$B...en je wordt overvallen door een scherpe kaasgeur. De kaas is een beetje nat, maar nog steeds lekker!",
  g = { {"zoektocht", "search"}, {"grondig", "thoroughly"}, {"spoor", "trace"}, {"aanwijzingen", "clues (aanwijzing)"}, {"aangeraakt", "touched (aanraken)"}, {"wrikt open", "pry open (openwrikken)"}, {"overvallen", "assaulted, overwhelmed"}, {"scherpe", "pungent, sharp (scherp)"}, {"kaasgeur", "smell of cheese"} },
},

[285] = { en = "Search More Hovels", tier = 2,
  t = "Doorzoek meer hutten",
  d = "Je bekijkt deze groep murlochutten grondig, maar je vindt niets.$B$B...maar je weet zeker dat je volgende aanwijzing iets oplevert.$B$BEen van de hutten in het noorden moet de Menethil Statuette hebben!",
  o = "Zoek verder in de murlochutten naar de Menethil Statuette.",
  c = "Dit vat ligt half begraven in de modder en het gras...",
  g = { {"doorzoek", "search (doorzoeken)"}, {"hutten", "hovels, huts (hut)"}, {"grondig", "thoroughly"}, {"aanwijzing", "clue"}, {"oplevert", "yields, turns out fruitful (opleveren)"}, {"begraven", "buried"}, {"modder", "mud"} },
},

[1651] = { en = "The Tome of Valor", tier = 2,
  t = "Het boek van moed",
  d = "Ik durf te wedden dat ze snel weer komen. Dus maak je klaar.$B$BIk heb een geweer in huis. Ik pak het en dan help ik je. Maar voor het grootste deel sta je er alleen voor.$B$BIk weet niet hoeveel ze er sturen. Maar het zijn er vast meer dan de paar van eerder.$B$BVraag het Licht om alle zegeningen die je kunt krijgen, want... hoorde je dat? Ik denk dat ze eraan komen.$B$BWe houden stand bij het huis!",
  o = "Verdedig Daphne Stilwell tegen de aanval van de Defias.$B$BJullie mogen geen van beiden sterven als je wilt slagen.$B$BPraat weer met Daphne Stilwell als het gelukt is.",
  p = "We houden stand bij het huis!",
  c = "Het is ons gelukt, $N! Bedankt voor je hulp. Je was echt geweldig daarbuiten. Ik had nooit gedacht dat een $C zoveel vijanden tegelijk aankon.$B$BJe hebt echt moed getoond tegen een enorme overmacht.",
  e = "Bescherm Daphne Stilwell",
  g = { {"durf te wedden", "I'd wager (durven, wedden)"}, {"geweer", "gun"}, {"sta je er alleen voor", "you're on your own (er alleen voor staan)"}, {"zegeningen", "blessings (zegening)"}, {"houden stand", "make a stand (standhouden)"}, {"verdedig", "defend (verdedigen)"}, {"geen van beiden", "neither of you"}, {"slagen", "to succeed"}, {"tegelijk", "at once, at the same time"}, {"aankon", "could handle (aankunnen)"}, {"getoond", "shown (tonen)"}, {"overmacht", "overwhelming odds, superior force"} },
},

[1652] = { en = "The Tome of Valor", tier = 2,
  t = "Het boek van moed",
  d = "Ga alsjeblieft terug naar Duthorian en laat hem weten dat ik voorlopig veilig ben. Dat heb ik aan jou en de Kerk te danken.$B$BHij stuurt een bericht naar Ironforge, zodat mijn Jordan weet dat hij niet bang hoeft te zijn.$B$BOh, wat mis ik mijn man. Ik kan niet wachten tot hij terugkomt.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Zo, we zien elkaar weer, $N. En je bent in een goed humeur, zie ik.$B$BHet huis van de Stilwells is weer een dag veilig. En uit je verhaal begrijp ik dat er gevaar genoeg was. Goed gedaan.$B$BDaphne en Jordan hebben de Kerk erg geholpen. Dat jij hun bezit beschermde, en zelfs hun leven, was het minste wat we voor hen konden doen.$B$BJe krijgt een beloning voor je moed.",
  g = { {"voorlopig", "for now"}, {"te danken", "to thank for (danken aan)"}, {"zodat", "so that"}, {"terugkomt", "comes back (terugkomen)"}, {"humeur", "mood, spirits"}, {"bezit", "property"}, {"het minste", "the least"}, {"beloning", "reward"} },
},

})

